# Terraform Refactor: Dev/Prod Blocks → for_each Module

This guide shows how to consolidate duplicated resource blocks into a reusable module using `for_each`, with zero-diff state migration.

## Current State (Before)

Your root `main.tf` likely has parallel blocks:

```hcl
# root/main.tf (BEFORE)

resource "aws_eks_cluster" "dev" {
  name            = "app-dev"
  role_arn        = aws_iam_role.eks_dev.arn
  vpc_config {
    subnet_ids = var.dev_subnets
  }
  version = "1.27"
}

resource "aws_eks_cluster" "prod" {
  name            = "app-prod"
  role_arn        = aws_iam_role.eks_prod.arn
  vpc_config {
    subnet_ids = var.prod_subnets
  }
  version = "1.27"
}

resource "aws_eks_node_group" "dev" {
  cluster_name       = aws_eks_cluster.dev.name
  nodegroup_name     = "app-dev-ng"
  node_role_arn      = aws_iam_role.node_dev.arn
  subnet_ids         = var.dev_subnets
  desired_size       = 2
  max_size           = 3
  instance_types     = ["t3.medium"]
}

resource "aws_eks_node_group" "prod" {
  cluster_name       = aws_eks_cluster.prod.name
  nodegroup_name     = "app-prod-ng"
  node_role_arn      = aws_iam_role.node_prod.arn
  subnet_ids         = var.prod_subnets
  desired_size       = 4
  max_size           = 6
  instance_types     = ["t3.large"]
}

# ... repeat for S3, RDS, IAM, ALB, etc.
```

## Target State (After)

### Step 1: Create the Module

Create `modules/app_infrastructure/main.tf`:

```hcl
# modules/app_infrastructure/main.tf

variable "environment_name" {
  type = string
}

variable "config" {
  type = object({
    cluster_name      = string
    node_count        = number
    node_instance_type = string
    region            = string
    subnets           = list(string)

    # S3
    s3_versioning     = bool
    s3_replication_region = optional(string)

    # RDS
    rds_instance_class = string
    rds_multi_az       = bool
    rds_backup_days    = number

    # HTTPS
    enable_cloudfront  = bool

    # IAM
    use_oidc_provider  = bool
  })
}

# EKS Cluster
resource "aws_eks_cluster" "cluster" {
  name            = var.config.cluster_name
  role_arn        = aws_iam_role.eks.arn
  version         = "1.27"

  vpc_config {
    subnet_ids = var.config.subnets
  }
}

resource "aws_eks_node_group" "nodes" {
  cluster_name       = aws_eks_cluster.cluster.name
  nodegroup_name     = "${var.environment_name}-ng"
  node_role_arn      = aws_iam_role.node.arn
  subnet_ids         = var.config.subnets
  desired_size       = var.config.node_count
  max_size           = var.config.node_count + 2
  instance_types     = [var.config.node_instance_type]

  depends_on = [aws_iam_role_policy_attachment.node_policy]
}

# IAM for EKS
resource "aws_iam_role" "eks" {
  name = "${var.environment_name}-eks-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_policy" {
  role       = aws_iam_role.eks.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node" {
  name = "${var.environment_name}-eks-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

# S3 Bucket
resource "aws_s3_bucket" "assets" {
  bucket = "${var.environment_name}-app-assets-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = var.config.s3_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Replication (prod only)
resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.config.s3_replication_region != null ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.assets]

  bucket = aws_s3_bucket.assets.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    status   = "Enabled"
    priority = 1

    destination {
      bucket       = "arn:aws:s3:::${var.environment_name}-app-assets-replica-${data.aws_caller_identity.current.account_id}"
      storage_class = "STANDARD"
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.config.s3_replication_region != null ? 1 : 0
  name  = "${var.environment_name}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

# RDS PostgreSQL
resource "aws_db_instance" "postgres" {
  identifier           = "${var.environment_name}-postgres"
  engine               = "postgres"
  engine_version       = "14.7"
  instance_class       = var.config.rds_instance_class
  allocated_storage    = 20
  storage_type         = "gp3"

  db_name  = "appdb"
  username = "postgres"
  password = aws_secretsmanager_secret_version.db_password.secret_string

  multi_az               = var.config.rds_multi_az
  publicly_accessible    = false
  storage_encrypted      = true
  backup_retention_period = var.config.rds_backup_days
  deletion_protection    = true
  skip_final_snapshot    = false
  final_snapshot_identifier = "${var.environment_name}-postgres-final-snapshot"

  db_subnet_group_name = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]
}

resource "aws_db_subnet_group" "postgres" {
  name       = "${var.environment_name}-postgres-subnet"
  subnet_ids = var.config.subnets
}

resource "aws_security_group" "rds" {
  name = "${var.environment_name}-rds-sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }
}

# Secrets Manager for DB password
resource "random_password" "db" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.environment_name}/db/password"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db.result
}

# IAM Service Account
resource "aws_iam_user" "app_service" {
  name = "${var.environment_name}-app-service"
}

resource "aws_iam_access_key" "app_service" {
  user = aws_iam_user.app_service.name
}

resource "aws_iam_user_policy" "app_service" {
  name = "${var.environment_name}-app-policy"
  user = aws_iam_user.app_service.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.db_password.arn
      }
    ]
  })
}

# Data source for account ID
data "aws_caller_identity" "current" {}

# Outputs
output "eks_cluster_name" {
  value = aws_eks_cluster.cluster.name
}

output "eks_cluster_endpoint" {
  value = aws_eks_cluster.cluster.endpoint
}

output "s3_bucket_id" {
  value = aws_s3_bucket.assets.id
}

output "rds_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

output "service_account_key_id" {
  value = aws_iam_access_key.app_service.id
}
```

### Step 2: Update Root Module

Replace duplicated blocks in `main.tf`:

```hcl
# root/main.tf (AFTER)

module "app_infrastructure" {
  for_each = var.environments

  source = "./modules/app_infrastructure"

  environment_name = each.key
  config           = each.value
}

# Output aggregated results
output "infrastructure" {
  value = {
    for env, module_output in module.app_infrastructure :
    env => {
      cluster_name    = module_output.eks_cluster_name
      cluster_endpoint = module_output.eks_cluster_endpoint
      s3_bucket       = module_output.s3_bucket_id
      rds_endpoint    = module_output.rds_endpoint
    }
  }
}
```

### Step 3: Define Environment Variables

Create `environments.tfvars`:

```hcl
# environments.tfvars

environments = {
  "dev" = {
    cluster_name           = "app-dev"
    node_count             = 2
    node_instance_type     = "t3.medium"
    region                 = "us-east-1"
    subnets                = ["subnet-dev-1", "subnet-dev-2"]

    s3_versioning          = true
    s3_replication_region  = null  # dev has no replication

    rds_instance_class     = "db.t3.micro"
    rds_multi_az           = false
    rds_backup_days        = 7

    enable_cloudfront      = false
    use_oidc_provider      = false
  }

  "prod" = {
    cluster_name           = "app-prod"
    node_count             = 4
    node_instance_type     = "t3.large"
    region                 = "us-east-1"
    subnets                = ["subnet-prod-1", "subnet-prod-2", "subnet-prod-3"]

    s3_versioning          = true
    s3_replication_region  = "us-west-2"  # prod has cross-region replication

    rds_instance_class     = "db.t3.medium"
    rds_multi_az           = true
    rds_backup_days        = 30

    enable_cloudfront      = true
    use_oidc_provider      = true
  }
}
```

## Zero-Diff State Migration

To migrate without recreating resources, run these `terraform state mv` commands **before** applying the refactored code:

```bash
# EKS Clusters
terraform state mv 'aws_eks_cluster.dev' 'module.app_infrastructure["dev"].aws_eks_cluster.cluster'
terraform state mv 'aws_eks_cluster.prod' 'module.app_infrastructure["prod"].aws_eks_cluster.cluster'

# EKS Node Groups
terraform state mv 'aws_eks_node_group.dev' 'module.app_infrastructure["dev"].aws_eks_node_group.nodes'
terraform state mv 'aws_eks_node_group.prod' 'module.app_infrastructure["prod"].aws_eks_node_group.nodes'

# IAM Roles (EKS)
terraform state mv 'aws_iam_role.eks_dev' 'module.app_infrastructure["dev"].aws_iam_role.eks'
terraform state mv 'aws_iam_role.eks_prod' 'module.app_infrastructure["prod"].aws_iam_role.eks'

# IAM Roles (Nodes)
terraform state mv 'aws_iam_role.node_dev' 'module.app_infrastructure["dev"].aws_iam_role.node'
terraform state mv 'aws_iam_role.node_prod' 'module.app_infrastructure["prod"].aws_iam_role.node'

# IAM Role Policy Attachments (EKS)
terraform state mv 'aws_iam_role_policy_attachment.eks_policy_dev' 'module.app_infrastructure["dev"].aws_iam_role_policy_attachment.eks_policy'
terraform state mv 'aws_iam_role_policy_attachment.eks_policy_prod' 'module.app_infrastructure["prod"].aws_iam_role_policy_attachment.eks_policy'

# IAM Role Policy Attachments (Nodes)
terraform state mv 'aws_iam_role_policy_attachment.node_policy_dev' 'module.app_infrastructure["dev"].aws_iam_role_policy_attachment.node_policy'
terraform state mv 'aws_iam_role_policy_attachment.node_policy_prod' 'module.app_infrastructure["prod"].aws_iam_role_policy_attachment.node_policy'

# S3 Buckets
terraform state mv 'aws_s3_bucket.dev' 'module.app_infrastructure["dev"].aws_s3_bucket.assets'
terraform state mv 'aws_s3_bucket.prod' 'module.app_infrastructure["prod"].aws_s3_bucket.assets'

# S3 Versioning
terraform state mv 'aws_s3_bucket_versioning.dev' 'module.app_infrastructure["dev"].aws_s3_bucket_versioning.assets'
terraform state mv 'aws_s3_bucket_versioning.prod' 'module.app_infrastructure["prod"].aws_s3_bucket_versioning.assets'

# S3 Encryption
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.dev' 'module.app_infrastructure["dev"].aws_s3_bucket_server_side_encryption_configuration.assets'
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.prod' 'module.app_infrastructure["prod"].aws_s3_bucket_server_side_encryption_configuration.assets'

# S3 Public Access Block
terraform state mv 'aws_s3_bucket_public_access_block.dev' 'module.app_infrastructure["dev"].aws_s3_bucket_public_access_block.assets'
terraform state mv 'aws_s3_bucket_public_access_block.prod' 'module.app_infrastructure["prod"].aws_s3_bucket_public_access_block.assets'

# S3 Replication (prod only)
terraform state mv 'aws_s3_bucket_replication_configuration.prod' 'module.app_infrastructure["prod"].aws_s3_bucket_replication_configuration.assets[0]'
terraform state mv 'aws_iam_role.s3_replication_prod' 'module.app_infrastructure["prod"].aws_iam_role.s3_replication[0]'

# RDS Instances
terraform state mv 'aws_db_instance.dev' 'module.app_infrastructure["dev"].aws_db_instance.postgres'
terraform state mv 'aws_db_instance.prod' 'module.app_infrastructure["prod"].aws_db_instance.postgres'

# RDS Subnet Groups
terraform state mv 'aws_db_subnet_group.dev' 'module.app_infrastructure["dev"].aws_db_subnet_group.postgres'
terraform state mv 'aws_db_subnet_group.prod' 'module.app_infrastructure["prod"].aws_db_subnet_group.postgres'

# RDS Security Groups
terraform state mv 'aws_security_group.rds_dev' 'module.app_infrastructure["dev"].aws_security_group.rds'
terraform state mv 'aws_security_group.rds_prod' 'module.app_infrastructure["prod"].aws_security_group.rds'

# Secrets Manager
terraform state mv 'aws_secretsmanager_secret.db_password_dev' 'module.app_infrastructure["dev"].aws_secretsmanager_secret.db_password'
terraform state mv 'aws_secretsmanager_secret.db_password_prod' 'module.app_infrastructure["prod"].aws_secretsmanager_secret.db_password'

terraform state mv 'aws_secretsmanager_secret_version.db_password_dev' 'module.app_infrastructure["dev"].aws_secretsmanager_secret_version.db_password'
terraform state mv 'aws_secretsmanager_secret_version.db_password_prod' 'module.app_infrastructure["prod"].aws_secretsmanager_secret_version.db_password'

# IAM Users & Access Keys
terraform state mv 'aws_iam_user.app_service_dev' 'module.app_infrastructure["dev"].aws_iam_user.app_service'
terraform state mv 'aws_iam_user.app_service_prod' 'module.app_infrastructure["prod"].aws_iam_user.app_service'

terraform state mv 'aws_iam_access_key.app_service_dev' 'module.app_infrastructure["dev"].aws_iam_access_key.app_service'
terraform state mv 'aws_iam_access_key.app_service_prod' 'module.app_infrastructure["prod"].aws_iam_access_key.app_service'

terraform state mv 'aws_iam_user_policy.app_service_dev' 'module.app_infrastructure["dev"].aws_iam_user_policy.app_service'
terraform state mv 'aws_iam_user_policy.app_service_prod' 'module.app_infrastructure["prod"].aws_iam_user_policy.app_service'
```

## Verification Workflow

```bash
# 1. Backup state
terraform state pull > terraform.state.backup

# 2. Run state moves (in order, or in a script)
# (see commands above)

# 3. Verify state is consistent
terraform state list | wc -l  # Should equal original count

# 4. Plan (should show no changes)
terraform plan -var-file=environments.tfvars

# 5. If plan is clean, apply
terraform apply -var-file=environments.tfvars
```

## Key Benefits

- **DRY**: Single source of truth for resource definitions
- **Scalability**: Adding a third environment is one entry in `environments.tfvars`
- **Consistency**: Drift is impossible between env definitions
- **Zero Downtime**: State moves preserve resource IDs; no recreation
- **Environment Parity**: Shared module ensures feature/config parity, with overrides only where needed
